    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 depositAmount, uint256 withdrawAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(depositAmount > 0);
        require(withdrawAmount > 0);
        require(withdrawAmount <= depositAmount);
        require(address(this).balance >= depositAmount);

        uint256 balanceBefore = address(c).balance;

        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        c.withdraw(withdrawAmount); if (__ESBMC_reverted()) return;

        uint256 balanceAfter = address(c).balance;

        assert(balanceAfter == balanceBefore + depositAmount - withdrawAmount);
    }

    receive() external payable {}
}

